{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score cannot establish consistency across runs."
        }
      ],
      "instrument_review": "Construction and scoring support interpreting the reported result as performance on these grid puzzles. Repeat-run consistency is undocumented, limiting conclusions about score stability."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Without repeated results, stability remains unknown; this does not demonstrate unstable scores."
        }
      ],
      "instrument_review": "Reporting clearly documents the absence of repeated evaluation. Exact-grid scoring describes how performance was scored, but does not establish consistency across runs."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations held the stated conditions constant."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability definition of at most two percentage points."
        }
      ],
      "instrument_review": "Repeated testing supports consistency under the specified conditions and stated stability criterion. This evidence remains limited to the evaluated system, puzzles, and conditions."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The developers examined repeated scores under the same stated conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's maximum stable range of two percentage points."
        }
      ],
      "instrument_review": "Repeated evaluation documents a consistency problem under the report's own criterion. The single 70% result cannot adequately represent the reported variability, which limits comparisons based on one run."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation guidance supplies no evidence that repeated evaluations occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions provide no repeated-score findings supporting stability."
        }
      ],
      "instrument_review": "Installation documentation explains setup, but adds no evidence about score consistency. The reported score remains limited to one reported run on the specified puzzles."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A achieved a higher result on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The findings do not establish comparative general intelligence across domains."
        }
      ],
      "instrument_review": "The evaluated content, exact-grid scoring, and fixed instructions support the narrow reported comparison, matching the intended use. Repeatability and other resource conditions are unspecified; cross-domain interpretation lacks evidence."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results support A's better performance on these evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The broad intended use does not supply evidence for cross-domain superiority."
        }
      ],
      "instrument_review": "The test content supports a grid-puzzle comparison, but the intended selection for general intelligence across domains exceeds the supplied evidence. Fixed instructions clarify one comparison condition; repeatability and other resource conditions remain unspecified."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial evidence supplies no demonstrated improvement in real workshop decisions with A compared with B."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial, blinded correctness checks, and reported difference interval support better correctness with A in the studied setting."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Correctness findings alone do not establish a workplace safety benefit."
        }
      ],
      "instrument_review": "The later preregistered randomized trial provides evidence directly relevant to choosing assistance for correct decisions in this workshop. Blinded checking and reported uncertainty strengthen interpretation. Findings do not establish effects on safety, time, or performance beyond the studied conditions."
    }
  ],
  "closing_note": "No material instruction ambiguity was identified. Missing evidence was distinguished from explicit conflicting evidence, and each case was assessed independently."
}
